head.script:
// https://inswave01.atlassian.net/browse/WAEA-1484
// 테스트 설명, 유효성 값 설정
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성)
//  - valueNotInList='keepValue' / autoComplete + noResult / chooseOption 관련 내용은 column_P_emptyItem_2.xml 에서 다룬다
scwin.tData = {
    "description" : "[column > P > emptyItem]<br/>inputType='select','autoComplete' 인 Column 에서 Cell 값이 목록에 없는 경우 처리 방식을 설정합니다.",
    "validation" : [
        "true 설정 시, Cell 값이 목록에 없으면 편집 모드에서 목록을 선택하지 않고 빈 값으로 표시합니다.",
        "true 설정 시, Cell 의 Value 값은 emptyValue 속성값을 갖습니다.",
        "false 설정 또는 미설정 시, Cell 값이 목록에 없으면 편집 모드에서 목록의 첫번째 아이템을 선택합니다.",
        "Cell 값이 ''(Empty String)이고 목록에 Value 값이 '' 인 항목이 없는 경우도 목록에 없는 값으로 처리됩니다.",
        "emptyItem=true 로 빈 값이 표시된 상태에서 목록을 열면 목록 영역에 빈 항목이 추가되지 않으며 첫번째 항목이 선택 대상으로 표시됩니다.",
        "keepEmptyState=true 로 설정하면 목록을 열어도 선택 대상 항목을 표시하지 않습니다."
    ]
}



scwin.gVar = {
    // 편집 상태 출력 타이머 (클릭 묶음 단위로 1회 출력)
    "timer" : null
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean 코드 "2" = true)
    con_emptyItem.setValue("2");
    con_keepEmptyState.setValue("");

    // 셀 더블클릭(편집 진입) / autoComplete 목록 버튼 클릭 후 편집 상태 자동 출력 (capture 단계, 1회만 등록)
    document.addEventListener("click", scwin.document_clickCapture, true);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - sel : inputType=select, ac : inputType=autoComplete (아이템 서울(S) / 부산(B) / 대구(D) 정적 정의)
//  - emptyItem / emptyValue / keepEmptyState 는 sel, ac 두 Column 에 동일 적용
//  - Row 0 : 목록에 있는 값(S), Row 1 : 목록에 없는 값(J), Row 2 : ''(Empty String)
scwin.comp_init = async function () {
    // 기존 타이머 / target / dataList / label 삭제
    if (scwin.gVar.timer) {
        clearTimeout(scwin.gVar.timer);
        scwin.gVar.timer = null;
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Row 0 = 목록에 있는 값(S), Row 1 = 목록에 없는 값(J), Row 2 = 빈 문자열\n[절차] sel / ac 셀 더블클릭 (sel 은 목록이 바로 열림, ac 는 셀 오른쪽 목록 버튼 클릭) -> 셀 밖 클릭으로 편집 종료 -> getCellData 확인\n[확인] 편집 진입 / 목록 열기마다 표시값, 선택 인덱스, 열린 목록과 선택 대상(*) 자동 출력"', '', 'label1');

    // 조건 설정 (gdl_boolean 은 getText() 로 '' / 'true' / 'false' 판단, 미설정은 속성 자체를 넣지 않는다)
    let cEmptyItem = con_emptyItem.getText();
    let cEmptyValue = con_emptyValue.getValue();
    let cKeepEmptyState = con_keepEmptyState.getValue();

    let attrCol = '';
    if (cEmptyItem !== '') {
        attrCol += ' emptyItem="' + cEmptyItem + '"';
    }
    if (cEmptyValue !== '') {
        attrCol += ' emptyValue="' + cEmptyValue + '"';
    }
    if (cKeepEmptyState !== '') {
        attrCol += ' keepEmptyState="' + cKeepEmptyState + '"';
    }

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="sel" name="sel" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ac" name="ac" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "sel" : "S", "ac" : "S" },
        { "name" : "김철수", "sel" : "J", "ac" : "J" },
        { "name" : "이영희", "sel" : "", "ac" : "" }
    ], false);

    // 정적 아이템
    let strItems = '';
    strItems += '<w2:choices>';
    strItems += '<w2:item><w2:label>서울</w2:label><w2:value>S</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>부산</w2:label><w2:value>B</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>대구</w2:label><w2:value>D</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column2" value="sel (select)"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="text" id="column3" value="ac (autoComplete)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="select" id="sel" value=""' + attrCol + '>' + strItems + '</w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="autoComplete" id="ac" value=""' + attrCol + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 클릭 묶음 집계 : 마지막 클릭 400ms 후 1회 출력 (더블클릭은 1회로 묶임)
scwin.document_clickCapture = function (e) {
    if (scwin.gVar.timer) {
        clearTimeout(scwin.gVar.timer);
    }
    scwin.gVar.timer = setTimeout(scwin.reportEditState, 400);
}



// 편집 중인 sel / ac 셀의 표시값 / 선택 인덱스 / 열린 목록과 선택 대상(*) 출력
//  - validation 1, 3, 4 : 표시값과 getSelectedIndex (Row 1 = 목록에 없는 값, Row 2 = 빈 문자열)
//  - validation 5, 6 : 목록이 열려 있으면 목록 항목(빈 항목 추가 여부)과 선택 대상(*) 표시
scwin.reportEditState = function () {
    scwin.gVar.timer = null;
    if (typeof target1 === 'undefined' || !target1 || !target1.isEditing()) {
        return;
    }
    let rowIndex = target1.getFocusedRowIndex();
    let colId = target1.getFocusedColumnID();
    if (colId !== "sel" && colId !== "ac") {
        return;
    }
    let td = document.querySelector("td[id='" + target1.id + "_cell_" + rowIndex + "_" + target1.getFocusedColumnIndex() + "']");
    let editorEl = td ? td.querySelector("[role='combobox']") : null;
    let editor = editorEl ? $p.getComponentById(editorEl.id) : null;
    if (!editor) {
        return;
    }
    // 표시값 : select 는 아이템 표시 영역(getText), autoComplete 는 입력창 값
    let displayText = (colId === "sel") ? editor.getText() : editorEl.querySelector("input").value;
    let line = "Row " + rowIndex + " " + colId + " 편집 : 표시값 '" + displayText + "' / getSelectedIndex " + editor.getSelectedIndex();

    // 열린 목록 항목 (선택 대상 = mouseover 강조 항목에 * 표시)
    let arrCell = Array.prototype.filter.call(document.querySelectorAll("[id^='" + editor.id + "_itemTable_']"), function (cell) {
        return /_itemTable_\d+$/.test(cell.id) && cell.getClientRects().length > 0;
    });
    if (arrCell.length > 0) {
        let arrItem = arrCell.map(function (cell) {
            return "'" + cell.textContent + "'" + (/_col_over/.test(cell.className) ? "*" : "");
        });
        line += " / 목록 " + arrItem.join(", ");
    }
    wf_body_bottom.getObj("scwin").setReturnValue(line);
}



// 전체 Row 의 sel / ac Cell 값 (validation 2 : 편집 종료 후 Value 값 = emptyValue, validation 3 : 첫번째 아이템 값 반영)
scwin.btn_getCellData_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        bottom.setReturnValue("Row " + i + " '" + target1.getCellData(i, "sel") + "' / '" + target1.getCellData(i, "ac") + "'");
    }
}
